content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.header h1 {
  font-size: 2rem;
  font-weight: bold;
  color: var(--primary-color);
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

@media (max-width: 768px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

.chart-card, .list-card {
  background-color: var(--card-bg);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  transition: background-color 0.2s;
}

.expense-item:hover {
  background-color: #f9fafb;
}

.expense-item.selected {
  background-color: #e0e7ff;
}

.selected-info {
  margin-top: 16px;
  padding: 12px;
  background-color: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  font-size: 0.95rem;
}

.total-amount {
  font-size: 1.25rem;
  font-weight: bold;
  margin-top: 16px;
  text-align: right;
  color: var(--primary-color);
}

.btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 0.95rem;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger-color);
}

.btn-danger:hover {
  background-color: var(--danger-hover);
}

.input-field {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 0.95rem;
  margin-bottom: 12px;
}

.input-field:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

form {
  margin-top: 20px;
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
}

export interface ExpenseChartProps {
  expenses: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}

export interface ExpenseListProps {
  expenses: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAdd: (item: Omit<ExpenseItem, 'id'>) => void;
  onDelete: (id: string) => void;
}

import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpenseChartProps } from '../types';

export default function ExpenseChart({ expenses = [], selectedId, onSelect }: ExpenseChartProps) {
  const total = expenses.reduce((sum, item) => sum + item.amount, 0);
  const selectedItem = expenses.find(item => item.id === selectedId);

  return (
    <div className="chart-card">
      <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '16px' }}>支出内訳</h2>
      <div style={{ width: '100%', height: 250 }}>
        {expenses.length === 0 ? (
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%', color: 'var(--text-muted)' }}>
            データがありません
          </div>
        ) : (
          <ResponsiveContainer>
            <PieChart>
              <Pie
                data={expenses}
                dataKey="amount"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={80}
                innerRadius={40}
                onClick={(entry: any) => entry && onSelect?.(entry.id)}
                style={{ cursor: 'pointer' }}
              >
                {expenses.map((entry) => (
                  <Cell
                    key={`cell-${entry.id}`}
                    fill={entry.color}
                    stroke={entry.id === selectedId ? '#1f2937' : '#fff'}
                    strokeWidth={entry.id === selectedId ? 2 : 1}
                  />
                ))}
              </Pie>
              <Tooltip formatter={(value: any) => [`¥${Number(value).toLocaleString()}`, '金額']} />
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>

      <div className="total-amount">
        合計: ¥{total.toLocaleString()}
      </div>

      {selectedItem && (
        <div className="selected-info">
          <strong>{selectedItem.name}</strong>: ¥{selectedItem.amount.toLocaleString()} ({Math.round((selectedItem.amount / (total || 1)) * 100)}%)
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { ExpenseListProps } from '../types';

export default function ExpenseList({ expenses = [], selectedId, onSelect, onAdd, onDelete }: ExpenseListProps) {
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [color, setColor] = useState('#4f46e5');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !amount) return;
    const numAmount = Number(amount);
    if (isNaN(numAmount) || numAmount <= 0) return;

    onAdd?.({
      name: name.trim(),
      amount: numAmount,
      color,
    });

    setName('');
    setAmount('');
  };

  const total = expenses.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="list-card">
      <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '16px' }}>支出項目一覧</h2>

      <div style={{ maxHeight: '240px', overflowY: 'auto' }}>
        {expenses.length === 0 ? (
          <p style={{ color: 'var(--text-muted)', textAlign: 'center', padding: '20px 0' }}>支出項目が登録されていません</p>
        ) : (
          expenses.map((item) => (
            <div
              key={item.id}
              className={`expense-item ${item.id === selectedId ? 'selected' : ''}`}
              onClick={() => onSelect?.(item.id)}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span style={{ width: '12px', height: '12px', borderRadius: '50%', backgroundColor: item.color, display: 'inline-block' }}></span>
                <span>{item.name}</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={{ fontWeight: 'bold' }}>¥{item.amount.toLocaleString()}</span>
                <button
                  type="button"
                  className="btn btn-danger"
                  style={{ padding: '4px 8px', fontSize: '0.8rem' }}
                  onClick={(e) => {
                    e.stopPropagation();
                    onDelete?.(item.id);
                  }}
                >
                  削除
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      <div className="total-amount">
        合計: ¥{total.toLocaleString()}
      </div>

      <form onSubmit={handleSubmit}>
        <h3 style={{ fontSize: '1rem', fontWeight: 'bold', marginBottom: '12px' }}>新規支出を追加</h3>
        <input
          type="text"
          className="input-field"
          placeholder="項目名（例: 食費）"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          type="number"
          className="input-field"
          placeholder="金額（例: 15000）"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '12px' }}>
          <label style={{ fontSize: '0.9rem', color: 'var(--text-muted)' }}>カラー:</label>
          <input
            type="color"
            value={color}
            onChange={(e) => setColor(e.target.value)}
            style={{ width: '40px', height: '32px', border: 'none', cursor: 'pointer', background: 'none' }}
          />
        </div>
        <button type="submit" className="btn" style={{ width: '100%' }}>追加する</button>
      </form>
    </div>
  );
}

import { useState } from 'react';
import './index.css';
import { ExpenseItem } from './types';
import ExpenseChart from './components/ExpenseChart';
import ExpenseList from './components/ExpenseList';

const initialExpenses: ExpenseItem[] = [
  { id: '1', name: '食費', amount: 45000, color: '#4f46e5' },
  { id: '2', name: '家賃', amount: 80000, color: '#10b981' },
  { id: '3', name: '光熱費', amount: 15000, color: '#f59e0b' },
  { id: '4', name: '通信費', amount: 8000, color: '#ef4444' },
  { id: '5', name: '娯楽', amount: 20000, color: '#8b5cf6' },
];

export default function App() {
  const [expenses, setExpenses] = useState<ExpenseItem[]>(initialExpenses);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const handleSelect = (id: string) => {
    setSelectedId(prev => prev === id ? null : id);
  };

  const handleAdd = (item: Omit<ExpenseItem, 'id'>) => {
    const newItem: ExpenseItem = {
      ...item,
      id: Date.now().toString(),
    };
    setExpenses(prev => [...prev, newItem]);
  };

  const handleDelete = (id: string) => {
    setExpenses(prev => prev.filter(item => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>家計支出管理アプリ</h1>
      </header>
      <main className="main-layout">
        <ExpenseChart
          expenses={expenses}
          selectedId={selectedId}
          onSelect={handleSelect}
        />
        <ExpenseList
          expenses={expenses}
          selectedId={selectedId}
          onSelect={handleSelect}
          onAdd={handleAdd}
          onDelete={handleDelete}
        />
      </main>
    </div>
  );
}
